-- ----------------------------
-- Table structure for reservoir
-- ----------------------------
DROP TABLE IF EXISTS `reservoir`;
CREATE TABLE `reservoir`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '水库id',
  `water_supply` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '所属供水工程',
  `code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '水库编码',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '水库名称',
  `longitude` decimal(10, 7) NOT NULL COMMENT '经度',
  `latitude` decimal(10, 7) NOT NULL COMMENT '纬度',
  `locate` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '水库所在位置',
  `registration_number` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '水库注册登记号',
  `administration_division` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '水库注册所在行政区划',
  `level` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '水库工程等级',
  `scale` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '水库工程规模',
  `total_storage_capacity` double NOT NULL COMMENT '总库容（万m3）',
