-- ----------------------------
-- Table structure for water_distributor
-- ----------------------------
DROP TABLE IF EXISTS `water_distributor`;
CREATE TABLE `water_distributor`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分水口编号',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '分水口名称',
  `county` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '所属区县',
  `town` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '所属乡镇',
  `village` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '所属村庄',
  `longitude` decimal(10, 7) NOT NULL COMMENT '分水口经度',
  `latitude` decimal(10, 7) NOT NULL COMMENT '分水口纬度',
  `water_supply` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '所属供水工程',
  `date` date NOT NULL COMMENT '建站年月',
  `manage_unit` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '管理单位',
  `address` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '地址',
  `RTU_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '分水口RTU编码',
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
