-- ----------------------------
-- Table structure for water_level
-- ----------------------------
DROP TABLE IF EXISTS `water_level`;
CREATE TABLE `water_level`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '监测点',
  `code` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '站码',
  `value` decimal(7, 3) NOT NULL COMMENT '监测值',
  `monitor_time` datetime NOT NULL COMMENT '监测时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `water_level_uindex`(`monitor_time` ASC) USING BTREE COMMENT '监测时间的唯一索引'
) ENGINE = InnoDB AUTO_INCREMENT = 8450 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

