-- Records of water_storage
-- ----------------------------

-- ----------------------------
-- Table structure for water_supply_project
-- ----------------------------
DROP TABLE IF EXISTS `water_supply_project`;
CREATE TABLE `water_supply_project`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '供水工程id',
  `project_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '供水工程名',
  `code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '供水工程代码',
  `type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '工程类型',
  `zone` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '所属分区',
  `design_supply` double NOT NULL COMMENT '设计日供水规模',
  `actual_supple` double NOT NULL COMMENT '实际日供水规模',
  `design_population` double NOT NULL COMMENT '设计供水人口',
  `village` int NOT NULL COMMENT '收益行政村数量',
  `population` double NOT NULL COMMENT '收益人口',
  `supply_number` double NOT NULL COMMENT '供水户数',
  `manage_department` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '工程主管部门',
  `manage_unit` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '工程管理单位',
  `area` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '供水范围',
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

